   {\string\newlabel{def: perturbations}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    Let $\varphi \in \text{Fml}_{\text{B}}(\mathcal{L}_D)$ be a bounded formula, $\mathcal{F} : \text{Term}(\varphi) \to \text{FOL}_{\mathbb{R}}$ an approximation and $\delta \in \mathbb{Q}^+$ a rational constant representing the level of perturbation. The \emph{universal $\delta$ perturbation of $\varphi$ relative to $\mathcal{F}$}, denoted as $\mathcal{A}^\forall_\mathcal{F}(\varphi, \delta)$ is defined inductively as follows:
    \begin{enumerate}
        \item For atomic formulas of the form $t \succeq 0$ ($\succeq~\in \{\geq, >\}$) where $t$ is function-free, the perturbation is the identity operator, i.e:
            \[\mathcal{A}^\forall_{\mathcal{F}}\left(t \succeq 0, \delta\right) = t \succeq 0\]
        \item For atomic formulas of the form $t(f(e), \vec{x}) \succeq 0$ where the term $e$ is function-free the perturbation is defined as:
            \[\mathcal{A}^\forall_{\mathcal{F}}\left(t(f(e), \vec{x}) \succeq 0, \delta\right) = \forall^{\mathcal{F}_{f(e)}(e) + [-\delta, \delta]} w~\mathcal{A}^\forall_{\mathcal{F}_{w \mapsto f(e)}}\left(t(w, \vec{x}) \succeq 0, \delta\right)\]
            where $w$ is a fresh variable, $\mathcal{F}_{f(e)}(e) + [-\delta, \delta]$ is carried out as an addition of intervals and $\mathcal{F}_{w \mapsto f(e)} : \text{Term}_F(t(w, \vec{x}) \succeq 0) \to \text{FOL}_{\mathbb{R}}$ is defined via
            \[\mathcal{F}_{w \mapsto f(e)}(\theta(w, \vec{x})) = \mathcal{F}(\theta(f(e), \vec{x}))\]
            for any function term $\theta(w, \vec{x}) \in \text{Term}_F(t(w, \vec{x}) \succeq 0)$. This carries out the construction illustrated in Example \ref{example:perturbing formulas}. 
        \item For connectives of the form $\varphi_1 \textbar \varphi_2, \varphi_1 \& \varphi_2$, we have
        \[\mathcal{A}^\forall_{\mathcal{F}}\left(\varphi_1 \textbar \varphi_2, \delta\right) = \mathcal{A}^\forall_{\mathcal{F}}\left(\varphi_1, \delta\right) \textbar \mathcal{A}^\forall_{\mathcal{F}}\left(\varphi_2, \delta\right)\]
        \[\mathcal{A}^\forall_{\mathcal{F}}\left(\varphi_1 \& \varphi_2, \delta\right) = \mathcal{A}^\forall_{\mathcal{F}}\left(\varphi_1, \delta\right) \& \mathcal{A}^\forall_{\mathcal{F}}\left(\varphi_2, \delta\right)\]

        \item For sub-formulas of the form $Q^{[a, b]}y~ \psi(y, \vec{x})$, the perturbation is defined as
        \[\mathcal{A}^\forall_{\mathcal{F}}\left(Q^{[a, b]}y~\psi(y, \vec{x}), \delta\right) = Q^{[a, b]}y~\mathcal{A}^\forall_{\mathcal{F}}\left(\psi(y, \vec{x}), \delta\right)\]
    \end{enumerate}
    It is natural to also consider the dual notion of \emph{existential $\delta$ perturbation of $\varphi$ relative to $\mathcal{F}$}, denoted $\mathcal{A}^\exists_{\mathcal{F}}\left(\varphi, \delta\right)$. The only difference being the following change for point (2):
    \[\mathcal{A}^\exists_{\mathcal{F}}\left(t(f(e), \vec{x}) \succeq 0, \delta\right) = \exists^{\mathcal{F}_{f(e)}(e) + [-\delta, \delta]} w~\mathcal{A}^\exists_{\mathcal{F}_{w \mapsto f(e)}}\left(t(w, \vec{x}) \succeq 0, \delta\right)\]
    Note that for both perturbations the set of free variables remain unchanged, and for $\delta_1 \geq \delta_2 > 0$ the perturbations are monotone:
    \begin{align*}
        &
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta_1\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, \delta_1\right)}
 \rightarrow 
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta_2\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, \delta_2\right)}
\\
        &
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta_2\right)}
    {\mathcal{A}^{\exists}_{\mathcal{F}}\left(\varphi, \delta_2\right)}
 \rightarrow 
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta_1\right)}
    {\mathcal{A}^{\exists}_{\mathcal{F}}\left(\varphi, \delta_1\right)}

    \end{align*}

Validity of the equivalence follows directly by structural induction, and provability follows from axiom  








  \text{\irref@doqear+\vargend} 
 since the equivalence itself is a formula in $\text{FOL}_{\mathbb{R}}$.

