   {\string\newlabel{thm: delta completeness}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    For every bounded sentence $\varphi \in \text{Sent}_{\text{B}}(\mathcal{L}_D)$, every $\delta \in \mathbb{Q}^+$, there are corresponding (computable) syntactic approximations $
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{}\left(\varphi, \delta\right)}
, 
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{}\left(\varphi, \delta\right)}
$ such that the following hold:
    \begin{itemize}
        \item If $\varphi$ is true, then the approximation $
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{}\left(\varphi, \delta\right)}
$ is provable
        \begin{align*}
            \mathbb{R}_D \models \varphi \implies& \vdash_{\text{\upshape\textsf{d{\kern-0.05em}L}}\xspace} 
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{}\left(\varphi, \delta\right)}
\\
            \intertext{\item If $\varphi$ is false, then the negation of the approximation $
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{}\left(\varphi, \delta\right)}
$ is provable}
            \mathbb{R}_D \models \neg \varphi \implies& \vdash_{\text{\upshape\textsf{d{\kern-0.05em}L}}\xspace} \neg
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{}\left(\varphi, \delta\right)}

        \end{align*}
        \item Furthermore, the following are provable.
        \begin{align*}
            \vdash_{\text{\upshape\textsf{d{\kern-0.05em}L}}\xspace} &~\varphi \rightarrow 
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{}\left(\varphi, \delta\right)}
\\
            \vdash_{\text{\upshape\textsf{d{\kern-0.05em}L}}\xspace} &~
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{}\left(\varphi, \delta\right)}
 \rightarrow \varphi
        \end{align*}
    \end{itemize}

Let $(\varphi, \delta) \in \text{Sent}_{\text{B}}(\mathcal{L}_D) \times \mathbb{Q}^+$ be given. Without loss generality, we may assume $\delta < \frac{1}{2}$ (one can always take $\delta = \min\left(\delta, \frac{1}{4}\right)$). Let $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ be a provable enclosure of $\varphi$ as computed by Theorem \ref{cor: compute provable enclosures}, and $\mathcal{F} : \text{Term}_F(\varphi) \to \text{FOL}_{\mathbb{R}}$ some provable $(I, \delta)$ admissible approximation which is guaranteed to (computably) exist by Theorem \ref{thm: provable approximations exist}. The desired approximations $
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{}\left(\varphi, \delta\right)}
, 
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{}\left(\varphi, \delta\right)}
$ can now be computably constructed as $
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, \delta\right)}
, 
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{\mathcal{F}}\left(\varphi, \delta\right)}
$, and provability follows directly by Theorem \ref{thm: proof rules for delta perturbations} and the fact that $\mathcal{F}$ is a provably admissible approximation.

The algorithm can simply output the desired strengthening $
    \ifthenelse{\isempty{}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{}\left(\varphi, \delta\right)}
$ as given by Theorem \ref{thm: delta completeness}. For output (2), the algorithm outputs the truth value of $\mathcal{A}^\forall(\varphi, \delta)$, which is computable as $\text{FOL}_{\mathbb{R}}$ is decidable. Thus, it remains to show (3) and output a syntactic proof of $\varphi$ in the event that $\mathcal{A}^\forall(\varphi, \delta)$ is true. Indeed, applying the proof rule  








