\if@filesw\immediate\write\@auxout 
   {\string\newlabel{def: robustness}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    Let $\varphi \in \text{Fml}(\mathcal{L}_F)$ be a bounded formula, and $D : FV(\varphi) \to \mathbb{I}\mathbb{Q}$ a domain of $\varphi$, $\varphi$ is said to be:
    \begin{enumerate}
        \item \emph{$\forall$-robust relative to $D$}, if there exists an enclosure $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ extending $D$ and a sequence of $I$ admissible approximations $(\mathcal{F}_\delta)_\delta : \text{Term}_{\text{F}}(\varphi) \to \text{FOL}_{\mathbb{R}}$ such that
        \[\left\llbracket \varphi \right\rrbracket_{D} = \bigcup_{\delta > 0} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
       \item \emph{$\exists$-robust relative to $D$}, if there exists an enclosure $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ extending $D$ and a sequence of $I$ admissible approximations $(\mathcal{F}_\delta)_\delta : \text{Term}_{\text{F}}(\varphi) \to \text{FOL}_{\mathbb{R}}$ such that
        \[\left\llbracket \varphi \right\rrbracket_{D} = \bigcap_{\delta > 0} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
    \end{enumerate}
    If $\varphi$ is a sentence, $\left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}$ (and likewise for $
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
$) is a monotone sequence in $\{\bot, \top\}$, hence the operators $\bigcup_{\delta > 0}, \bigcap_{\delta > 0}$ can be replaced by $\lim_{\delta \to 0}$. In the case that a formula $\psi$ is both $\forall$ and $\exists$-robust relative to $D$, $\psi$ is said to be \emph{strongly robust relative to $D$}.

\if@filesw\immediate\write\@auxout 
   {\string\newlabel{thm: chacterization of robustness}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    Let $\varphi \in \text{Fml}_{\text{B}}(\mathcal{L}_D)$ be a bounded formula and $D : FV(\varphi) \to \mathbb{I}\mathbb{Q}$ a domain of $\varphi$. The following are equivalent:
    \begin{enumerate}
        \item $\varphi$ is $\forall$-robust relative to $D$.
        \item For \emph{all} enclosures $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ of $\varphi$ extending $D$, for \emph{all} sequences of $I$ admissible approximations $(\mathcal{F}_\delta)_\delta$, the following holds:
        \[\left\llbracket \varphi \right\rrbracket_{D} = \bigcup_{\delta > 0} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
    \end{enumerate}
    Dual equivalences hold for $\exists$-robustness.
    \begin{enumerate}
        \item $\varphi$ is $\exists$-robust relative to $D$.
        \item For \emph{all} enclosures $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ of $\varphi$ extending $D$, for \emph{all} sequences of $I$ admissible approximations $(\mathcal{F}_\delta)_\delta$, the following holds:
        \[\left\llbracket \varphi \right\rrbracket_{D} = \bigcap_{\delta > 0} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
    \end{enumerate}

An alternate interpretation of Theorem \ref{thm: chacterization of robustness} is that robust sentences are \emph{exactly} those with ``continuous truth values'' in the following sense: Let $T : \text{Sent}_{\text{B}}(\mathcal{L}_D) \to \{0, 1\}$ be the evaluation function defined by:
    \begin{align*}
        &T(\varphi) = 1 \iff \varphi \in \text{Th}_{\text{B}}(\mathbb{R}_D)\\
        &T(\varphi) = 0 \iff \varphi \notin \text{Th}_{\text{B}}(\mathbb{R}_D)
    \end{align*}
    Then a sentence $\varphi \in \text{Sent}_{\text{B}}(\mathcal{L}_D)$ is $\forall$-robust if and only if 
    \[\lim_{\delta \to 0} T(
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
) = T(\varphi)\]
    for all $I$ admissible approximations $(\mathcal{F}_\delta)_\delta$. Similarly, $\varphi$ is $\exists$-robust if and only if
    \[\lim_{\delta \to 0} T(
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
) = T(\varphi)\]
    thus $\varphi$ is strongly robust if and only if
    \[\lim_{\delta \to 0} T(
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\exists}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\exists}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
) = \lim_{\delta \to 0} T(
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
) = T(\varphi)\]

\if@filesw\immediate\write\@auxout 
   {\string\newlabel{lem: mont perturbations}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    Let $\varphi \in \text{Fml}_{\text{B}}(\mathcal{L}_D)$ be a bounded formula, $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ an enclosure, $0 < \delta < \frac{1}{2}$ and $\mathcal{F}: \text{Term}_{\text{F}}(\varphi) \to \text{FOL}_{\mathbb{R}}$ an $(I, \delta)$ admissible approximation. Then for all $(I, \frac{\delta - \left\lVertF\right\rVert_I}{2})$ admissible approximations $\mathcal{G} : \text{Term}_{\text{F}}(\varphi) \to \text{FOL}_{\mathbb{R}}$, the following hold ($I$ is identified with the domain $I\lvert_{FV(\varphi)}$):
    \[I \models 
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, \delta\right)}
 \rightarrow 
    \ifthenelse{\isempty{\mathcal{G}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}\right)}
    {\mathcal{A}^{\forall}_{\mathcal{G}}\left(\varphi, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}\right)}
\]

$(1)\!\implies\!(2)$: As $\varphi$ is $\forall$-robust relative to $D$, let $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ be an enclosure extending $D$ and $(\mathcal{F}_\delta)_\delta : \text{Term}_{\text{F}}(\varphi) \to \text{FOL}_{\mathbb{R}}$ a sequence of $I$ admissible approximations such that 
    \[\left\llbracket \varphi \right\rrbracket_{D} = \bigcup_{\delta > 0} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
    For an arbitrary enclosure $J : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ extending $D$ and an arbitrary sequence of $J$ admissible approximations $(\mathcal{G}_\varepsilon)_\varepsilon$, we need to establish the following (the converse is trivial as $(\mathcal{G}_\varepsilon)_\varepsilon$ is admissible):
    \[\left\llbracket \varphi \right\rrbracket_{D} \subseteq \bigcup_{\varepsilon > 0} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{G}_\varepsilon}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \varepsilon\right)}
    {\mathcal{A}^{\forall}_{\mathcal{G}_\varepsilon}\left(\varphi, \varepsilon\right)}
 \right\rrbracket_{D}\]
    let $I \cap J$ denote the enclosure defined by $(I \cap J)_e \coloneqq I_e \cap J_e$. Since $(\mathcal{F}_\delta)_\delta$ is $I$ admissible, it is furthermore $I \cap J$ admissible, and the same applies to $(\mathcal{G}_\varepsilon)_\varepsilon$. Lemma \ref{lem: mont perturbations} shows that for all $\delta$, for all sufficiently small $\varepsilon > 0$ satisfying $\varepsilon < \frac{\delta - \left\lVert\mathcal{F}\right\rVert_{I \cap J}}{2}$, the following hold
    \[\left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D} \subseteq \left\llbracket 
    \ifthenelse{\isempty{\mathcal{G}_\varepsilon}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \varepsilon\right)}
    {\mathcal{A}^{\forall}_{\mathcal{G}_\varepsilon}\left(\varphi, \varepsilon\right)}
 \right\rrbracket_{D}\]
    Consequently, this yields the desired:
    \[\left\llbracket \varphi \right\rrbracket_{D} = \bigcup_{\delta} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D} \subseteq \bigcup_{\varepsilon} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{G}_\varepsilon}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \varepsilon\right)}
    {\mathcal{A}^{\forall}_{\mathcal{G}_\varepsilon}\left(\varphi, \varepsilon\right)}
 \right\rrbracket_{D}\]
    $(2) \implies (1)$: This follows directly by definition of robustness.\\
    Corresponding equivalences for $\exists$-robustness can be obtained by taking the contrapositive and using Lemma \ref{lem: perturbation of negated formulas}.

\if@filesw\immediate\write\@auxout 
   {\string\newlabel{lem: continuously choose perturbation}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    Let $\varphi \in \text{Fml}_{\text{B}}^{>}(\mathcal{L}_D)$ be a bounded formula, $D : FV(\varphi) \to \mathbb{I}\mathbb{Q}$ a domain of $\varphi$ and $I : \text{Term}(\varphi) \to \mathbb{I}\mathbb{Q}$ an enclosure of $\varphi$ extending $D$. There exists a continuous function $m^I_\varphi : D \to [0, \sfrac{1}{4}]$ such that the following are equivalent for all $\vec{z} \in D$:
    \begin{enumerate}
        \item $\vec{z} \in \left\llbracket \varphi \right\rrbracket_{D}$
        \item $m^I_\varphi(\vec{z}) > 0$
        \item $m^I_\varphi(\vec{z}) > 0$ and $B_{D}(\vec{z}, m^I_\varphi(\vec{z})) \subseteq \left\llbracket \varphi \right\rrbracket_{D}$
        \item $m^I_\varphi(\vec{z}) > 0$ and $\vec{z} \in \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, m^I_\varphi(\vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, m^I_\varphi(\vec{z})\right)}
 \right\rrbracket_{D}$ for all $(I, m^I_\varphi(\vec{z}))$ admissible approximations $\mathcal{F}$.
    \end{enumerate}
    where $B_{D}(\vec{z}, r)$ denotes $B(\vec{z}, r) \cap D$.

We prove the $(1)-(4)$ by simultaneous induction for all $\varphi(\vec{x})$, first inducting over the number of function symbols and secondly inducting over the structural complexity, showing it for all $D, I$ at once. 
    \begin{itemize}
        \item $\varphi(\vec{x})$ is function free: In this case, $m^I_\varphi(\vec{x})$ can be defined as the function $\min(r_\varphi(\vec{x}), \sfrac{1}{4})$ given by Lemma \ref{lem: continuously choose interior}. Properties $(1)-(3)$ are satisfied by Lemma \ref{lem: continuously choose interior} and $(4)$ is satisfied as the perturbation $
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, m^I_\varphi(\vec{x})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, m^I_\varphi(\vec{x})\right)}
$ of a function-free formula $\varphi$ is the original formula $\varphi$ itself. 

         \item $\varphi(\vec{x}) \equiv \psi(f(e), \vec{x})$, where $e$ is function-free and $\psi$ is quantifier-free: Consider the formula $\psi(w, \vec{x})$ equipped with the enclosure $J \coloneqq I_{w \mapsto f(e)}$ extending the domain $E \coloneqq D \cup \{w \mapsto I_{f(e)}\}$. Applying the inductive hypothesis on $\psi(w, \vec{x})$ then yields a function $m^J_{\psi} : E \to [0, \sfrac{1}{4}]$ with properties $(1) - (4)$. Define the following auxiliary continuous functions on the domain $D \subseteq \mathbb{R}^n$
        \begin{align*}
            m_1(\vec{z}) &= \frac{1}{4}m^J_\psi(f(e(\vec{z})), \vec{z})\\
            m_2(\vec{z}) &= \min_{\substack{\lvert\lambda - f(e(\vec{z}))\rvert \leq 2m_1(\vec{z}) \\ \lambda \in I_{f(e)}}} m^J_\psi(\lambda, \vec{z})
        \end{align*}
        which are well defined by the extreme value theorem and noting that $f(e(\vec{z})) \in I_{f(e)}$ for $\vec{z} \in D$. Finally, $m^I_\varphi(\vec{z})$ can be constructed via the following where $r_\varphi(\vec{z})$ is the function given by Lemma \ref{lem: continuously choose interior} for $\varphi(\vec{x})$
        \[m^I_\varphi(\vec{z}) \coloneqq \min(r_\varphi(\vec{z}), m_1(\vec{z}), m_2(\vec{z}))\]
        Note that $m^I_\varphi$ is indeed continuous as taking pointwise minimums/minimums over compact intervals are continuous operations, so it remains to verify the equivalence of properties $(1) - (4)$. 
        \begin{itemize}
            \item $(1) \implies (2)$: Suppose $\vec{z} \in \left\llbracket \varphi \right\rrbracket_{D}$ holds. Since $r_\varphi(\vec{z}) > 0$ follows directly by Lemma \ref{lem: continuously choose interior} and $(f(e(\vec{z})), \vec{z}) \in \left\llbracket \psi \right\rrbracket_E$ implies $m_1(\vec{z}) > 0$ by inductive hypothesis, it suffices to show $m_2(\vec{z}) > 0$. To this end, consider any $\lambda \in I_{f(e)}$ such that $\lvert\lambda - f(e(\vec{z}))\rvert \leq 2m_1(\vec{z})$, we want to show $m^J_\psi(\lambda, \vec{z}) > 0$. Since $\vec{z} \in \left\llbracket \varphi \right\rrbracket_{D}$, this gives 
            \begin{align*}
                \vec{z} \in \left\llbracket \varphi \right\rrbracket_{D} &\implies (f(e(\vec{z})), \vec{z}) \in \left\llbracket \psi \right\rrbracket_E       \end{align*}
            Applying the inductive hypothesis $(3)$, it follows that
            \[B_{E}((f(e(\vec{z})), \vec{z}), m^J_\psi(f(e(\vec{z})), \vec{z})) \subseteq \left\llbracket \psi \right\rrbracket_E\]
            By construction and the fact that $m^J_\psi(f(e(\vec{z})), \vec{z}) > 0$, this gives
            \[\lvert\lambda - f(e(\vec{z}))\rvert \leq 2m_1(\vec{z}) = \frac{1}{2}m^J_\psi(f(e(\vec{z})), \vec{z}) < m^J_\psi(f(e(\vec{z})), \vec{z})\]
            Therefore
            \[\left\lVert(\lambda, \vec{z}) - (f(e(\vec{z})) , \vec{z})\right\rVert = \lvert\lambda - f(e(\vec{z}))\rvert < m^J_\psi(f(e(\vec{z})), \vec{z})\]
            implying
            \[(\lambda, \vec{z}) \in B_{E}((f(e(\vec{z})), \vec{z}), m^J_\psi(f(e(\vec{z})), \vec{z})) \implies (\lambda, \vec{z}) \in \left\llbracket \psi \right\rrbracket_E\]
            another application of the inductive hypothesis $(2)$ then gives
            \[m^J_\psi(\lambda, \vec{z}) > 0\]
            establishing the claim. 

            \item $(2) \implies (3)$: By definition of $m^I_\varphi$, $m^I_\varphi(\vec{z}) > 0$ implies $r_\varphi(\vec{z}) > 0$, from which $(3)$ follows by Lemma \ref{lem: continuously choose interior}.

            \item $(3) \implies (4)$: Let $\mathcal{F}$ be an arbitrary $(I, m^I_\varphi(\vec{z}))$ admissible approximation.  Recall that the $\delta$-perturbation of $\varphi(\vec{x})$ for an approximation $\mathcal{F}$ gives:

            \[
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, m^I_\varphi(\vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, m^I_\varphi(\vec{z})\right)}
 = \forall^{[-m^I_\varphi(\vec{z}), m^I_\varphi(\vec{z})] + \mathcal{F}_{f(e)}(e)} w~
    \ifthenelse{\isempty{\mathcal{F}_{w \mapsto f(e)}}}
    {\mathcal{A}^{\forall}\!\left(\psi, m^I_\varphi(\vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_{w \mapsto f(e)}}\left(\psi, m^I_\varphi(\vec{z})\right)}
\]

            Let $w$ be arbitrary satisfying $\lvertw - \mathcal{F}_{f(e)}(e(\vec{z}))\rvert \leq m^I_\varphi(\vec{z})$, it remains to establish 

            \[(w, \vec{z}) \in \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_{w \mapsto f(e)}}}
    {\mathcal{A}^{\forall}\!\left(\psi, m^I_\varphi(\vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_{w \mapsto f(e)}}\left(\psi, m^I_\varphi(\vec{z})\right)}
 \right\rrbracket_E\]

            To this end, first notice that by construction of $J$, the approximation $\mathcal{G} \coloneqq \mathcal{F}_{w \mapsto f(e)}$ is $(J, m^I_{\varphi}(\vec{z}))$ admissible. By admissibility of $\mathcal{F}$, $w$ satisfies
            \begin{align*}
                \lvertw - \mathcal{F}_{f(e)}(e(\vec{z}))\rvert \leq m^I_\varphi(\vec{z}) &\implies \lvertw - f(e(\vec{z}))\rvert \leq 2m^I_\varphi(\vec{z})\\
                &\implies \lvertw - f(e(\vec{z}))\rvert \leq \frac{1}{2}m^J_\psi(f(e(\vec{z})), \vec{z})\\
                &\implies (w, \vec{z}) \in B_E((f(e(\vec{z})), \vec{z}), m^J_\psi(f(e(\vec{z})), \vec{z}))
            \end{align*}
            where $w \in I_{f(e)}$ follows from the admissibility of $\mathcal{F}$ and $m^I_\varphi(\vec{z}) < \sfrac{1}{2}$. Since $0 < m^I_\varphi(\vec{z}) \leq m^J_{\psi}(f(e(\vec{z})), \vec{z})$, this implies 
            \[B_E((f(e(\vec{z})), \vec{z}), m^J_\psi(f(e(\vec{z})), \vec{z})) \subseteq \left\llbracket \psi \right\rrbracket_E \implies (w, \vec{z}) \in \left\llbracket \psi \right\rrbracket_E\]
            By definition of $m^J_\psi(w, \vec{x})$, and applying inductive hypothesis $(4)$, this further implies
            \begin{align*}
                (w, \vec{z}) \in \left\llbracket 
    \ifthenelse{\isempty{\mathcal{G}}}
    {\mathcal{A}^{\forall}\!\left(\psi, m^J_\psi(w, \vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{G}}\left(\psi, m^J_\psi(w, \vec{z})\right)}
 \right\rrbracket_E
            \end{align*}
            Thus, it remains to show $m^I_\varphi(\vec{z}) \leq m^J_\psi(w, \vec{z})$. It follows by construction of $m_2(\vec{z})$ that $m_2(\vec{z}) \leq m^J_\psi(w, \vec{z})$ as $w \in I_{f(e)}$ and $\lvertw - f(e(\vec{z}))\rvert \leq 2m_1(\vec{z})$, thus $m^I_\varphi(\vec{z}) \leq m^J_\psi(w, \vec{z})$, completing the proof as desired. 

            \item $(4) \implies (1)$: This follows directly from Theorem \ref{thm: proof rules for delta perturbations} as $
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, \delta\right)}
 \rightarrow \varphi$ is always (provably) valid for admissible approximations $\mathcal{F}$. 
        \end{itemize}

        \item $\varphi(\vec{x}) \equiv \exists^{[a, b]}y\psi(y, \vec{x})$: First note that an enclosure $I$ of $\varphi$ is also an enclosure of $\psi$, extending the domain $E \coloneqq D \cup \{y \mapsto I_y\}$. Similar to the previous case, $m^I_\varphi$ can be constructed as follows
        \begin{align*}
            &m_2(\vec{z}) = \max_{w \in [a(\vec{z}), b(\vec{z})]} m^I_\psi(w, \vec{z})\\
            &m^I_\varphi(\vec{z}) = \min(r_\varphi(\vec{z}), m_2(\vec{z}))
        \end{align*}
        Since $m^I_\varphi(\vec{z}) \leq r_\varphi(\vec{z})$, the equivalence of properties $(1), (2), (3)$ amounts to proving $(1) \implies m_2(\vec{z}) > 0$ where $\vec{z} \in D$ satisfies $(1)$. Indeed, we have
        \[\vec{z} \in \left\llbracket \varphi \right\rrbracket_{D} \implies \mathbf{\exists}^{[a(\vec{z}), b(\vec{z})]} w~(w, \vec{z}) \in \left\llbracket \psi \right\rrbracket_E\]
        Therefore, there is some $w \in [a(\vec{z}), b(\vec{z})]$ where $m^I_\psi(w, \vec{z}) > 0$ and therefore
        \[m_2(\vec{z}) \geq m_\psi(w, \vec{z}) > 0\]
        so properties $(1), (2), (3)$ are equivalent and it suffices to show $(2) \implies (4)$. As such, assume that $(2)$ is satisfied and fix some $\vec{z} \in D$ with $m^I_\varphi(\vec{z}) > 0$. Further denote $w \in [a(\vec{z}), b(\vec{z})]$ as some element attaining $m^I_\psi(w, \vec{z}) = m_2(\vec{z}) \geq m^I_\varphi(\vec{z}) > 0$. Standard manipulations conclude:
        \begin{align*}
            m^I_\psi(w, \vec{z}) > 0 &\implies (w, \vec{z}) \in \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\psi, m^I_\psi(w, \vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\psi, m^I_\psi(w, \vec{z})\right)}
 \right\rrbracket_E\\
            &\implies \vec{z} \in \left\llbracket \exists^{[a, b]}y~
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\psi, m^I_\psi(w, \vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\psi, m^I_\psi(w, \vec{z})\right)}
 \right\rrbracket_{D}\\
            &\implies \vec{z} \in \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\varphi, m^I_\varphi(\vec{z})\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\varphi, m^I_\varphi(\vec{z})\right)}
 \right\rrbracket_{D}
        \end{align*}

        \item $\varphi(\vec{x}) \equiv \forall^{[a, b]}y~\psi(y, \vec{x})$: Similar to the case above, define:
        \begin{align*}
            &m_2(\vec{z}) = \min_{w \in [a(\vec{z}), b(\vec{z})]} m_\psi(w, \vec{z})\\
            &m^I_\varphi(\vec{z}) = \min(r_\varphi(\vec{z}), m_2(\vec{z}))
        \end{align*}
        and the rest of the argument is identical to the existential case above. This completes the final case in our induction and the proof is therefore complete. \qedhere
    \end{itemize}

First consider the case where $\varphi \in \text{Fml}^>_B(\mathcal{L}_D)$, let $D$ be any domain of $\varphi$ and $I$ any enclosure extending $D$, which necessarily (computably) exists by Theorem \ref{thm: compute enclosures} and $(\mathcal{F}_\delta)_\delta$ an arbitrary sequence of $I$ admissible approximations. By Theorem \ref{thm: proof rules for delta perturbations}, it suffices to establish that 
    \[\left\llbracket \varphi \right\rrbracket_{D} \subseteq \bigcup_{\delta > 0} \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
    Let $m^I_\varphi : D \to [0, \sfrac{1}{4}]$ be the function given by Lemma \ref{lem: continuously choose perturbation}, and suppose $\vec{z} \in \left\llbracket \varphi \right\rrbracket_{D}$. It then follows by monotonicity of perturbations that for all sufficiently small $\delta > 0$ satisfying $\delta \leq m^I_\varphi(\vec{z})$ the following holds
    \[\vec{z} \in \left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
    since $\vec{z} \in D$ is arbitrary, this gives
    \[\left\llbracket \varphi \right\rrbracket_{D} = \bigcup_{\vec{z} \in \left\llbracket \varphi \right\rrbracket_{D}} \{\vec{z}\} \subseteq \bigcup_{\delta > 0 }\left\llbracket 
    \ifthenelse{\isempty{\mathcal{F}_\delta}}
    {\mathcal{A}^{\forall}\!\left(\varphi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}_\delta}\left(\varphi, \delta\right)}
 \right\rrbracket_{D}\]
    thus $\varphi$ is indeed $\forall$-robust. Now consider the case where $\varphi(\vec{x}) \in \text{Fml}^\geq_B(L_D)$, which implies $\neg\varphi(\vec{x}) \in \text{Fml}^>_B(L_D)$ when the negation is pushed through the quantifiers. It has already been established that $\neg\varphi$ is $\forall$-robust, therefore it follows by definition that $\varphi$ is $\exists$-robust, completing the proof.

