Recall that the differentially-defined function $h$ is annotated with some IVP having provable global existence. Without loss of generality, further assume that the IVP starts at time $t_0 = 0$, i.e. it is of the form
    \begin{align*}
        &x' = f(x)\\
        &x(0) = X
    \end{align*}
    Since the IVP has global existence, its solution $\varphi : \mathbb{R} \to \mathbb{R}^n$ is well-defined and Theorem \ref{thm: stone weierstrass for IVPs} applies. Consequently, we may compute polynomials $\theta^{+}(t), \theta^{-}(t) \in \mathbb{Q}^n[t]$ such that the following are provable
    \begin{align}
        x = X \& t = 0 &\rightarrow [#x' = f(x), t' = 1 \& t \leq T]#\left\lVertx - \theta^{+}(t)\right\rVert^2 < (\sfrac{\varepsilon}{4})^2 \if@filesw\immediate\write\@auxout 
   {\string\newlabel{fml: fwd time approx}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi\\
        x = X \& t = 0 &\rightarrow [#x' = -f(x), t' = -1 \& t \geq -T]#\left\lVertx - \theta^{-}(t)\right\rVert^2 < (\sfrac{\varepsilon}{4})^2 \if@filesw\immediate\write\@auxout 
   {\string\newlabel{fml: bwd time approx}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    \end{align}
    Let $p \in \mathbb{Q}[t]$ be any polynomial such that $\left\lVertp - h\right\rVert_{[-T, T]} < \sfrac{\varepsilon}{4}$ holds, which necessarily (computably) exists by the classical Stone-Weierstrass theorem. It then follows that the following are valid formulas of $\text{FOL}_{\mathbb{R}}$ and therefore provable with axiom $ 








  \text{\irref@doqear+\vargend} 
$. 
    \begin{align}
         0 \leq t \leq T &\rightarrow \lvertp(t) - \theta^+_0(t)\rvert < \sfrac{\varepsilon}{2} \if@filesw\immediate\write\@auxout 
   {\string\newlabel{fml: fwd time poly}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi\\
        -T \leq t \leq 0 &\rightarrow \lvertp(t) - \theta^-_0(t)\rvert < \sfrac{\varepsilon}{2} \if@filesw\immediate\write\@auxout 
   {\string\newlabel{fml: bwd time poly}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    \end{align}
    where $\theta^+_0, \theta^-_0$ denote the first-coordinate projections of $\theta^+$ and $\theta^-$ respectively. On the other hand, applying axiom  








  \text{\irref@doFI+\vargend} 
 in conjunction with the formulas (\ref{fml: fwd time approx}), (\ref{fml: bwd time approx}) proves the following 
    \begin{align}
        0 \leq t \leq T &\rightarrow \lverth(t) - \theta^+_0(t)\rvert < \sfrac{\varepsilon}{4} \if@filesw\immediate\write\@auxout 
   {\string\newlabel{fml: fwd time error bound}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi\\
        -T \leq t \leq 0 &\rightarrow \lverth(t) - \theta^-_0(t)\rvert < \sfrac{\varepsilon}{4} \if@filesw\immediate\write\@auxout 
   {\string\newlabel{fml: bwd time error bound}{{\arabic{HilbertRuleAppCounter}}{\thepage}}}\fi
    \end{align}
    combining formulas (\ref{fml: fwd time error bound})+(\ref{fml: fwd time poly}) and (\ref{fml: bwd time error bound})+(\ref{fml: bwd time poly}) proves the following
    \begin{align*}
        0 \leq t \leq T &\rightarrow \lverth(t) - p(t)\rvert < \sfrac{3\varepsilon}{4}\\
        -T \leq t \leq 0 &\rightarrow \lverth(t) - p(t)\rvert < \sfrac{3\varepsilon}{4}
    \end{align*}
    which then combines to prove the desired formula (\ref{fml: error bound}).

Let $\psi(\vec{x}, \vec{y})$ denote the quantifier-free part of $\varphi(\vec{x})$ (recall that $\varphi(\vec{x})$ is assumed to be in prenex normal form), where $\vec{x}$ are the free variables and $\vec{y}$ are the bound variables. By construction of the perturbations, it suffices to show that $
    \ifthenelse{\isempty{\mathcal{F}}}
    {\mathcal{A}^{\forall}\!\left(\psi, \delta\right)}
    {\mathcal{A}^{\forall}_{\mathcal{F}}\left(\psi, \delta\right)}
 \rightarrow 
    \ifthenelse{\isempty{\mathcal{G}}}
    {\mathcal{A}^{\forall}\!\left(\psi, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}\right)}
    {\mathcal{A}^{\forall}_{\mathcal{G}}\left(\psi, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}\right)}
$ is valid in $I$. This can be proven inductively by first inducting on the number of function terms and then on the structural complexity:
    \begin{itemize}
        \item The base case where $\varphi$ does not contain functions is trivial, since perturbation is the identity in this case. 
        \item The cases of boolean connectives and quantifiers hold trivially by inductive hypothesis.
        \item Consider the non-trivial case of $\psi \equiv t(f(e), \vec{z}) \succeq 0$ where $\vec{z} = (\vec{x}, \vec{y})$ and the term $e(\vec{z})$ is function-free. The perturbations corresponding to $\mathcal{F}, \mathcal{G}$ are:
        \begin{align*}
            &\mathcal{A}^\forall_{\mathcal{F}}\left(t(f(e), \vec{z}) \succeq 0, \delta\right) = \forall^{[-\delta, \delta] + \mathcal{F}_{f(e)}(e)} w~\mathcal{A}^\forall_{\mathcal{F}_{w \mapsto f(e)}}\left(t(w, \vec{z}) \succeq 0, \delta\right)\\
            &\mathcal{A}^\forall_{\mathcal{G}}\left(t(f(e), \vec{z}) \succeq 0, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}\right) = \forall^{\left[-\frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}\right] + \mathcal{G}_{f(e)}(e)} w~ \mathcal{A}^\forall_{\mathcal{G}_{w \mapsto f(e)}}\left(t(w, \vec{z}) \succeq 0, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}\right)
        \end{align*}
        By applying the inductive hypothesis on $t(w, \vec{z}) \succeq 0$ with enclosure $I_{w \mapsto f(e)}$, it suffices to show that $\lvertw - \mathcal{G}_{f(e)}(e)\rvert \leq \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2} \implies \lvertw - \mathcal{F}_{f(e)}(e)\rvert \leq \delta$. To this end, let $w \in \mathbb{R}$ be a witness to $\lvertw - \mathcal{G}_{f(e)}(e)\rvert \leq \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2}$. Since $\mathcal{G}$ is $(I, \frac{\delta - \left\lVert\mathcal{F}\right\rVert_I}{2})$ admissible, this necessarily implies that $\lvertw - f(e)\rvert < \delta - \left\lVert\mathcal{F}\right\rVert_I$. Consequently, the triangle inequality gives
        \[\lvertw - \mathcal{F}_{f(e)}(e)\rvert \leq \lvertw - f(e)\rvert + \left\lVert\mathcal{F}\right\rVert_I < \delta\]
        which completes the proof by induction.
    \end{itemize}
    To obtain corresponding results for existential perturbations, one could either follow the proof above but use $\mathcal{A}^\exists$ instead, or utilize Lemma \ref{lem: perturbation of negated formulas} and directly apply duality.
